    views_path,views_sha=artifact(root,out_dir,"P5_PC6_PRECOMPUTABLE_STRUCTURAL_VIEWS_V1",
                                  {"generated_at":now_iso(),"VIEW_A":view_a,"VIEW_B":view_b})

    h0_ready=bool(executable and complete_wave1)
    t1_ready=bool(executable and complete_t1)
    ready=bool(h0_ready or t1_ready)
