        try: fcntl.flock(lock.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError as e: raise RuntimeError(f"MATERIALIZER_ALREADY_RUNNING:{args.root}") from e
        if args.command in ("enumerate","all"): enumerate_plan(args.root,args.workers)
        if args.command in ("download","all"): download_plan(args.root,args.workers)
        if args.command in ("normalize","all"): normalize_all(args.root,Path(__file__),args.workers)
