def previous_fully_closed_bar(bars: Sequence[Mapping[str, Any]],
                              decision_us: int) -> Mapping[str, Any]:
    eligible = [bar for bar in bars if int(bar["close_us"]) <= decision_us - 1000]
    if not eligible:
        raise EvaluationError("no fully closed bar")
    return max(eligible, key=lambda row: int(row["close_us"]))


def log_basis(perp: np.float64, spot: np.float64) -> np.float64:
    if perp <= 0 or spot <= 0 or not np.isfinite(perp) or not np.isfinite(spot):
        raise EvaluationError("FORMULA_UNDEFINED_ON_FROZEN_INPUTS")
    return FLOAT(np.log(perp) - np.log(spot))


def funding_return(position_sign: np.float64, funding_rate: np.float64) -> np.float64:
    return FLOAT(-FLOAT(position_sign) * FLOAT(funding_rate))


def funding_in_open_closed(events: Sequence[Mapping[str, Any]], start_us: int,
                           end_us: int, position_sign: np.float64) -> np.float64:
    values = [funding_return(position_sign, FLOAT(e["funding_rate"]))
              for e in events if start_us < int(e["market_event_time_us"]) <= end_us]
    return FLOAT(np.sum(np.asarray(values, dtype=np.float64), dtype=np.float64))


def return_components(entry_f: np.float64, exit_f: np.float64,
                      entry_s: np.float64, exit_s: np.float64,
                      funding: np.float64) -> dict[str, np.float64]:
    values = enforce_float64(np.array([entry_f, exit_f, entry_s, exit_s, funding],
                                      dtype=np.float64), "return inputs")
    if np.any(values[:4] <= 0):
        raise IntegrityVoid("I9", "nonpositive price")
    spot = FLOAT(np.log(exit_s) - np.log(entry_s))
    term = FLOAT((np.log(exit_f) - np.log(exit_s)) -
                 (np.log(entry_f) - np.log(entry_s)))
    total = FLOAT(np.log(exit_f) - np.log(entry_f) + funding)
    decomposed = FLOAT(spot + term + funding)
    if total != decomposed and abs(float(total - decomposed)) > np.finfo(np.float64).eps * 8:
        raise IntegrityVoid("I9", "TOTAL decomposition identity failed")
    return {"TOTAL": total, "SPOT": spot, "TERM": term, "FUNDING": FLOAT(funding)}


def freeze_quintile_weights(features: Mapping[str, np.float64]) -> dict[str, Any]:
    rows = []
    for symbol, value in features.items():
        value = FLOAT(value)
        if np.isfinite(value):
            rows.append((symbol.encode("utf-8"), symbol, value))
    rows.sort(key=lambda row: (row[2], row[0]))
    n = len(rows)
    if n < 5:
        return {"state": "STRUCTURALLY_UNDEFINED", "n": n, "weights": {}}
    groups: dict[int, list[str]] = {q: [] for q in range(1, 6)}
    for rank, (_, symbol, _) in enumerate(rows, 1):
        q = min(4, math.floor(5 * (rank - 1) / n)) + 1
        groups[q].append(symbol)
    if any(not symbols for symbols in groups.values()):
        return {"state": "STRUCTURALLY_UNDEFINED", "n": n, "weights": {}}
    weights: dict[str, np.float64] = {}
    for symbol in groups[1]:
        weights[symbol] = FLOAT(1.0 / len(groups[1]))
    for symbol in groups[5]:
        weights[symbol] = FLOAT(-1.0 / len(groups[5]))
    frozen = {"state": "FROZEN", "n": n, "groups": groups,
              "weights": weights,
              "weight_path_sha256": digest(canonical_bytes(
                  {k: float(v) for k, v in sorted(weights.items())}))}
    return frozen


@dataclass
class LabelGate:
    """Synthetic/production-neutral structural gate; labels remain private."""
    _labels: Mapping[str, Mapping[str, np.float64]]
    allowed_end_us: int
    _opened: bool = False
    _frozen_weights_hash: str | None = None

    def open(self, frozen: Mapping[str, Any], authority_applied: bool,
             label_end_us: int) -> None:
        if self._opened:
            raise IntegrityVoid("I6", "label gate already opened")
        if not authority_applied:
            raise IntegrityVoid("I5", "authority not APPLIED")
        if frozen.get("state") != "FROZEN" or not frozen.get("weight_path_sha256"):
            raise IntegrityVoid("I6", "weights not frozen before label access")
        if label_end_us > self.allowed_end_us:
            raise IntegrityVoid("I6", "label read beyond permitted development window")
        self._frozen_weights_hash = str(frozen["weight_path_sha256"])
        self._opened = True

    def read(self, symbol: str) -> Mapping[str, np.float64] | None:
        if not self._opened:
            raise IntegrityVoid("I6", "label access before weight freeze")
        return self._labels.get(symbol)


def evaluate_frozen_portfolio(frozen: Mapping[str, Any], gate: LabelGate) -> dict[str, Any]:
    if frozen.get("state") != "FROZEN":
        return {"state": "STRUCTURALLY_UNDEFINED"}
    total = FLOAT(0.0); spot = FLOAT(0.0); term = FLOAT(0.0); funding = FLOAT(0.0)
    missing = 0

    missing = 0
    for symbol, weight in frozen["weights"].items():
        row = gate.read(symbol)
        if row is None:
            missing += 1
            continue  # frozen weight is NOT renormalized
        w = FLOAT(weight)
        total = FLOAT(total + w * FLOAT(row["TOTAL"]))
        spot = FLOAT(spot + w * FLOAT(row["SPOT"]))
        term = FLOAT(term + w * FLOAT(row["TERM"]))
        funding = FLOAT(funding + w * FLOAT(row["FUNDING"]))
    return {"state": "OUTCOME_COMPLETE" if missing == 0 else "OUTCOME_INCOMPLETE",
            "TOTAL": total, "SPOT": spot, "TERM": term, "FUNDING": funding,
            "OUTCOME_INCOMPLETE": missing,
            "frozen_weight_path_sha256": frozen["weight_path_sha256"]}


def filtering_first_counterexample(features: Mapping[str, np.float64],
                                   labels: Mapping[str, Any]) -> bool:
    correct = freeze_quintile_weights(features)
    filtered = freeze_quintile_weights({k: v for k, v in features.items() if k in labels})
    return correct.get("weight_path_sha256") != filtered.get("weight_path_sha256")


def hac_lag(estimator_t: int, horizon_hours: int) -> int:
    if estimator_t < 1 or horizon_hours not in (8, 24, 168):
        raise EvaluationError("unsupported HAC inputs")
    plug_in = math.floor(4 * (estimator_t / 100) ** (2 / 9))
    overlap_floor = horizon_hours // 8 - 1
    return max(overlap_floor, plug_in)


def hac_mean(series: np.ndarray, horizon_hours: int) -> dict[str, Any]:
    x = enforce_float64(series, "HAC series")
    t = len(x)
    m = hac_lag(t, horizon_hours)
    centered = x - np.mean(x, dtype=np.float64)
    gamma0 = FLOAT(np.dot(centered, centered) / t)
    lrv = gamma0
    for j in range(1, min(m, t - 1) + 1):
        gamma = FLOAT(np.dot(centered[j:], centered[:-j]) / t)
        lrv = FLOAT(lrv + 2 * (1 - j / (m + 1)) * gamma)
    info1 = t >= m + 2
    info2 = bool(np.isfinite(lrv) and lrv > 0)
    se = FLOAT(np.sqrt(lrv / t)) if info1 and info2 else FLOAT(np.nan)
    mean = FLOAT(np.mean(x, dtype=np.float64))
    construction_t = FLOAT(mean / se) if np.isfinite(se) and se > 0 else FLOAT(np.nan)
    return {"mean": mean, "hac_lag": m, "long_run_variance": lrv,
            "hac_se": se, "construction_t": construction_t,
            "ESTIMATOR_T": t, "INFO_1": info1, "INFO_2": info2,
            "INFO": info1 and info2}


def result_state(integrity_pass: bool, info: bool, estimate: np.float64,
                 two_sided_p: np.float64) -> str:
    if not integrity_pass:
        return "TEST_VOIDED"
    if not info:
        return "EVIDENCE_INSUFFICIENT_CURRENT_COHORT"
    if estimate > 0 and two_sided_p < FLOAT(0.05):
        return "REPLICATION_SUPPORTED"
    return "REPLICATION_FAILED"


def two_sided_normal_p(construction_t: np.float64) -> np.float64:
    if not np.isfinite(construction_t):
        raise IntegrityVoid("I9", "non-finite construction t")
    return FLOAT(math.erfc(abs(float(construction_t)) / math.sqrt(2.0)))


def t1_result_artifact(series: np.ndarray, components: Sequence[Mapping[str, Any]],
                       integrity_pass: bool = True) -> dict[str, Any]:
    stats = hac_mean(series, 8)
    p = two_sided_normal_p(stats["construction_t"]) if stats["INFO"] else None
    state = result_state(integrity_pass, stats["INFO"], stats["mean"],
                         FLOAT(p) if p is not None else FLOAT(1.0))
    complete = [row for row in components if row.get("state") == "OUTCOME_COMPLETE"]
    def mean_field(field: str) -> float | None:
        return (float(np.mean(np.asarray([row[field] for row in complete], dtype=np.float64),
                              dtype=np.float64)) if complete else None)
    return {
        "result_state": state, "gross_mean": float(stats["mean"]),
        "hac_se": None if not np.isfinite(stats["hac_se"]) else float(stats["hac_se"]),
        "construction_t": None if not np.isfinite(stats["construction_t"]) else float(stats["construction_t"]),
        "two_sided_normal_p": p, "ESTIMATOR_T": stats["ESTIMATOR_T"],
        "INFO_1": stats["INFO_1"], "INFO_2": stats["INFO_2"], "INFO": stats["INFO"],
        "spot_component": mean_field("SPOT"), "term_component": mean_field("TERM"),
        "funding_component": mean_field("FUNDING"),
        "OUTCOME_INCOMPLETE": sum(row.get("state") == "OUTCOME_INCOMPLETE" for row in components),
        "STRUCTURALLY_UNDEFINED": sum(row.get("state") == "STRUCTURALLY_UNDEFINED" for row in components),
        "acf_decay": "REPORT_ONLY", "variance_ratio": "REPORT_ONLY",
    }


def fee_only_diagnostic(horizon_hours: int, turnover: np.float64 | None) -> float | str:
    if horizon_hours != 8:
        return "UNAVAILABLE"
    if turnover is None or not np.isfinite(turnover) or turnover < 0:
        raise EvaluationError("8h turnover required for fee-only diagnostic")
    return float(FLOAT(turnover) * TAKER_FEE_PER_SIDE)


def wave1_diagnostic(candidate: Mapping[str, Any], series: np.ndarray,
                     long_leg: np.ndarray, short_leg: np.ndarray,
                     components: Sequence[Mapping[str, Any]], turnover: np.float64 | None,
                     source_alignment_t: np.float64 | None = None) -> dict[str, Any]:
    horizon = int(candidate["holding_horizon_hours"])
    stats = hac_mean(series, horizon)
    for name, values in (("long_leg", long_leg), ("short_leg", short_leg)):
        enforce_float64(values, name)
    complete = [row for row in components if row.get("state") == "OUTCOME_COMPLETE"]
    def component(field: str) -> float | None:
        return float(np.mean(np.asarray([r[field] for r in complete], dtype=np.float64),
                             dtype=np.float64)) if complete else None
    total_count = len(components)
    return {
        "candidate_id": candidate["candidate_id"], "gross_mean": float(stats["mean"]),
        "net_fee_only_mean": fee_only_diagnostic(horizon, turnover),
        "hac_se": None if not np.isfinite(stats["hac_se"]) else float(stats["hac_se"]),
        "construction_t": None if not np.isfinite(stats["construction_t"]) else float(stats["construction_t"]),
        "ESTIMATOR_T": stats["ESTIMATOR_T"], "effective_information_note": "HAC_INFO=" + str(stats["INFO"]),
        "long_leg_mean": float(np.mean(long_leg, dtype=np.float64)),
        "short_leg_mean": float(np.mean(short_leg, dtype=np.float64)),
        "funding_component": component("FUNDING"), "term_component": component("TERM"),
        "spot_component": component("SPOT"), "turnover": None if turnover is None else float(turnover),
        "coverage": (len(complete) / total_count if total_count else 0.0),
        "OUTCOME_INCOMPLETE": sum(r.get("state") == "OUTCOME_INCOMPLETE" for r in components),
        "STRUCTURALLY_UNDEFINED": sum(r.get("state") == "STRUCTURALLY_UNDEFINED" for r in components),
        "SOURCE_ALIGNMENT_T": None if source_alignment_t is None else float(source_alignment_t),
    }


def risc_record(wave_id: str, candidate_list_sha256: str, candidate_count: int,
                attempted: int, completed: int, rejected: Mapping[str, int]) -> dict[str, Any]:
    if candidate_count != 174 or attempted > candidate_count or completed > attempted:
        raise IntegrityVoid("I5", "RISC scope/count mismatch")
    if any(key not in REJECTION_RULES or value < 0 for key, value in rejected.items()):
        raise IntegrityVoid("I5", "RISC rejection rule mismatch")
    record = {"wave_id": wave_id, "candidate_list_sha256": candidate_list_sha256,
              "candidate_count": candidate_count, "attempted": attempted,
              "completed": completed, "rejected": dict(sorted(rejected.items()))}
    record["risc_sha256"] = digest(canonical_bytes(record))
    return record


def rejection_reason(feature_values: np.ndarray, candidate_hash: str,
                     weight_path_sha256: str, seen_candidates: set[str],
                     seen_paths: set[str]) -> str | None:
    x = enforce_float64(feature_values, "candidate feature")
    if len(x) == 0:
        return "FORMULA_UNDEFINED_ON_FROZEN_INPUTS"
    if np.var(x, ddof=0, dtype=np.float64) == FLOAT(0.0):
        return "EXACT_ZERO_XS_VARIANCE"
    if candidate_hash in seen_candidates:
        return "DUPLICATE_CANDIDATE_HASH"
    if weight_path_sha256 in seen_paths:
        return "DUPLICATE_WEIGHT_PATH"
    seen_candidates.add(candidate_hash); seen_paths.add(weight_path_sha256)
    return None


def enforce_i12_source(source_path: str | os.PathLike[str]) -> None:
    import ast
    tree = ast.parse(Path(source_path).read_text(encoding="utf-8"))
    for node in ast.walk(tree):
        roots: list[str] = []
        if isinstance(node, ast.Import): roots = [alias.name.split(".")[0] for alias in node.names]
        elif isinstance(node, ast.ImportFrom) and node.module: roots = [node.module.split(".")[0]]
        if BANNED_IMPORT_ROOTS.intersection(roots):
            raise IntegrityVoid("I12", f"banned import: {sorted(BANNED_IMPORT_ROOTS.intersection(roots))}")


def feature_value(core: str, history: Mapping[str, np.ndarray], lookback_days: int | None) -> np.float64:
    y = enforce_float64(history["basis"], "basis")
    if core == "LB_LEVEL": return FLOAT(y[-1])
    if core == "BASIS_CHANGE_1CYCLE": return FLOAT(y[-1] - y[-2])
    if core == "BASIS_ACCEL_1CYCLE": return FLOAT((y[-1]-y[-2])-(y[-2]-y[-3]))
    if lookback_days is None: raise EvaluationError("lookback required")
    n = 3 * lookback_days
    if core == "BASIS_PERSISTENCE_L":
        z = y[-n:]; return FLOAT(np.mean(np.sign(z) == np.sign(y[-1])))
    if core == "BM_EQ70_L":
        sr=enforce_float64(history["spot_returns"],"spot_returns")[-n:]
        fr=enforce_float64(history["perp_returns"],"perp_returns")[-n:]
        return FLOAT(np.prod(1+sr,dtype=np.float64)-np.prod(1+fr,dtype=np.float64))
    pv=enforce_float64(history["quote_volume"],"quote_volume")[-n:]
    imb=enforce_float64(history["signed_quote_volume"],"signed_quote_volume")[-n:]
    if core == "PV_L":
        m=FLOAT(np.mean(pv,dtype=np.float64));
        if m <= 0: raise EvaluationError("FORMULA_UNDEFINED_ON_FROZEN_INPUTS")
        return FLOAT(np.log(m))
    if core == "PV_VAR_L": return FLOAT(np.var(pv,ddof=0,dtype=np.float64))
    if core == "PV_IMB_L": return FLOAT(np.mean(imb,dtype=np.float64))
    if core == "PV_IMB_VAR_L": return FLOAT(np.var(imb,ddof=0,dtype=np.float64))
    if core == "DAMIHUD_L":
        if np.any(pv == 0): raise EvaluationError("FORMULA_UNDEFINED_ON_FROZEN_INPUTS")
        fr=enforce_float64(history["perp_returns"],"perp_returns")[-n:]
        return FLOAT(np.mean(np.abs(fr)/pv,dtype=np.float64))
    raise EvaluationError("unknown frozen feature core")
